  width: 20px; height: 20px; border-radius: 4px;
}
.error-banner .x:hover { background: rgba(0,0,0,.06); }

/* ---------- 主布局 ---------- */
.layout { flex: 1; display: flex; min-height: 0; padding: 10px 14px; gap: 10px; }
.tree-panel {
  flex: 1; min-width: 0; display: flex; flex-direction: column;
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  overflow: hidden;
}
.panel-cap {
  flex: none; padding: 7px 12px; font-size: 11px; font-weight: 600;
