            h("input", {
              id: "searchInput", type: "search", placeholder: "搜索名称 / 编码…",
              "aria-label": "搜索实体名称或编码",
              oninput: function (ev) {
                el("searchBox").classList.toggle("has-value", !!ev.target.value);
                actions.setQuery(ev.target.value);
              }
            }),
            h("button", {
