          h("span", { class: "scope", id: "scope", "aria-live": "off" })
        ),
        h("div", { class: "toolbar-row" },
          h("span", { class: "sel-chip", id: "selChip" }),
          h("div", { class: "menu-anchor" },
            h("button", {
              class: "btn caret", id: "btnStatus", onclick: function () { actions.toggleMenu(); }
            }, "变更状态"),
