          h("button", { class: "btn quiet", id: "btnClearSel", onclick: function () { actions.clearSelection(); } }, "清除选择"),
          h("span", { class: "vr", "aria-hidden": "true" }),
          h("button", { class: "btn quiet", id: "btnUndoBar", onclick: function () { actions.undo(); } }, "↺ 撤销")
        )
      ),
