      var a = ids.indexOf(state.anchorId), b = ids.indexOf(id);
      if (a >= 0 && b >= 0) {
        var lo = Math.min(a, b), hi = Math.max(a, b);
        for (var i = lo; i <= hi; i++) state.selected.add(ids[i]);
