1	/* =====================================================================
2	 * 实体台账管理台 — app.js
3	 *
4	 * 模式：PAT-LIST-DETAIL-INSPECTOR
5	 *   tree_table（dominant workspace） + selection_inspector（contextual inspector）
6	 *   + toolbar（persistent command bar） + batch_preview_modal / receipt / status_bar
7	 *
8	 * 零误伤核心不变量（choice_selection_scope「可见即作用域」）：
9	 *   1. 选择集 selected 只存显式勾选的实体 id；
10	 *   2. 行/分组/全选的任何勾选入口，只作用于“当前渲染可见”的实体行；
11	 *      折叠分支、被搜索/筛选隐藏的实体在机制上进不了选择集；
12	 *   3. 批量操作执行前必须经过影响预览模态（按归属路径分组 + 计数），
13	 *      执行后回执“已影响 N 项”并可一步撤销。
14	 *
15	 * 状态所有权（SDIR state_ownership）：
16	 *   selection -> state.selected（显式 id 集合）      query -> state.query/statusFilter
17	 *   viewport  -> state.collapsed（展开映射）          preview -> state.modal（模态控制器）
18	 *   inspector -> 由 selected 派生，不独立持有状态
19	 * ===================================================================== */
20	(function () {
21	  "use strict";
22	
23	  /* ---------------- 工具 ---------------- */
24	  function h(tag, attrs) {
25	    var el = document.createElement(tag);
26	    if (attrs) {
27	      Object.keys(attrs).forEach(function (k) {
28	        var v = attrs[k];
29	        if (v === null || v === undefined || v === false) return;
30	        if (k === "class") el.className = v;
31	        else if (k === "text") el.textContent = v;
32	        else if (k === "checked") el.checked = true;
33	        else if (k === "indeterminate") el.indeterminate = true;
34	        else if (k.slice(0, 2) === "on" && typeof v === "function") el.addEventListener(k.slice(2), v);
35	        else el.setAttribute(k, v === true ? "" : String(v));
36	      });
37	    }
38	    for (var i = 2; i < arguments.length; i++) appendChild(el, arguments[i]);
39	    return el;
40	  }
41	  function appendChild(el, c) {
42	    if (c === null || c === undefined || c === false) return;
43	    if (Array.isArray(c)) { c.forEach(function (x) { appendChild(el, x); }); return; }
44	    el.appendChild(c.nodeType ? c : document.createTextNode(String(c)));
45	  }
46	  function el(id) { return document.getElementById(id); }
47	  function pad(n, w) { return String(n).padStart(w, "0"); }
48	  function nowTime() { return new Date().toLocaleTimeString("zh-CN", { hour12: false }); }
49	
50	  /* ---------------- 数据索引 ---------------- */
51	  var groups = window.REGISTRY_DATA.groups;
52	  var groupById = new Map();
53	  var childrenOf = new Map();     // groupId -> 子分组[]
54	  var ROOTS = [];
55	  groups.forEach(function (g) {
56	    groupById.set(g.id, g);
57	    if (g.parentId) {
58	      if (!childrenOf.has(g.parentId)) childrenOf.set(g.parentId, []);
59	      childrenOf.get(g.parentId).push(g);
60	    } else ROOTS.push(g);
61	  });
62	
63	  var entityById = new Map();     // id -> entity
64	  var entitiesByGroup = new Map();// groupId -> 直接实体[]
65	  window.REGISTRY_DATA.entities.forEach(function (e) { indexEntity(e); });
66	  function indexEntity(e) {
67	    entityById.set(e.id, e);
68	    if (!entitiesByGroup.has(e.groupId)) entitiesByGroup.set(e.groupId, []);
69	    entitiesByGroup.get(e.groupId).push(e);
70	  }
71	  childrenOf.forEach(function (list) {
72	    list.sort(function (a, b) { return a.name < b.name ? -1 : 1; });
73	  });
74	
75	  var PATH = new Map();           // groupId -> 名称路径[]
76	  function pathOfGroup(id) {
77	    if (PATH.has(id)) return PATH.get(id);
78	    var g = groupById.get(id);
79	    var p = g.parentId ? pathOfGroup(g.parentId).concat([g.name]) : [g.name];
80	    PATH.set(id, p);
81	    return p;
82	  }
83	  function pathTextOfGroup(id) { return pathOfGroup(id).join(" / "); }
84	  function entityPath(e) { return pathTextOfGroup(e.groupId); }
85	
86	  var STATUS = {
87	    online:      { label: "在线",   cls: "st-online" },
88	    maintenance: { label: "维护中", cls: "st-maintenance" },
89	    retired:     { label: "停用",   cls: "st-retired" }
90	  };
91	  var STATUS_KEYS = ["online", "maintenance", "retired"];
92	
93	  /* ---------------- 状态 ---------------- */
94	  // phase: "loading"（状态机完备性保留，数据内联故同步就绪） | "ready" | "error"
95	  var state = {
96	    phase: "ready",
97	    collapsed: new Set(),          // 已折叠分组（默认全展开，层级首屏即见）
98	    selected: new Set(),           // 显式选择集：实体 id
99	    query: "",
100	    statusFilter: "all",
101	    modal: null,                   // {kind:"status"|"move"|"delete", target, error}
102	    receipt: null,                 // {text, changed:[...], undo, undone}
103	    error: null,                   // {text}
104	    anchorId: null,                // shift 范围选择锚点
105	    focusRowId: null,
106	    lastOpText: "—",
107	    visibleEntityCount: 0,
108	    menuOpen: false
109	  };
110	
111	  /* ---------------- 选择器 ---------------- */
112	  function queryText() { return state.query.trim().toLowerCase(); }
113	  function filterActive() { return queryText() !== "" || state.statusFilter !== "all"; }
114	  function matchesFilter(e) {
115	    if (state.statusFilter !== "all" && e.status !== state.statusFilter) return false;
116	    var q = queryText();
117	    if (q && e.name.toLowerCase().indexOf(q) < 0 && e.code.toLowerCase().indexOf(q) < 0) return false;
118	    return true;
119	  }
120	  function directEntities(gid) { return entitiesByGroup.get(gid) || []; }
121	
122	  // 展开后的可见行（树表渲染序：子分组在前，直接实体在后）
123	  function buildRows() {
124	    var rows = [];
125	    function hasMatch(g) {
126	      var d = directEntities(g.id);
127	      for (var i = 0; i < d.length; i++) if (matchesFilter(d[i])) return true;
128	      var subs = childrenOf.get(g.id) || [];
129	      for (var j = 0; j < subs.length; j++) if (hasMatch(subs[j])) return true;
130	      return false;
131	    }
132	    function subtreeTotal(g) {
133	      var n = directEntities(g.id).length;
134	      (childrenOf.get(g.id) || []).forEach(function (s) { n += subtreeTotal(s); });
135	      return n;
136	    }
137	    function walk(g, depth, anc) {
138	      if (!hasMatch(g)) return;
139	      var directVisible = directEntities(g.id).filter(matchesFilter);
140	      var expanded = filterActive() ? true : !state.collapsed.has(g.id);
141	      rows.push({
142	        kind: "group", g: g, depth: depth, expanded: expanded,
143	        directVisible: directVisible.length,
144	        directTotal: directEntities(g.id).length,
145	        subtreeTotal: subtreeTotal(g)
146	      });
147	      if (expanded) {
148	        (childrenOf.get(g.id) || []).forEach(function (s) { walk(s, depth + 1, anc.concat([s.id])); });
149	        directVisible.forEach(function (e) {
150	          rows.push({ kind: "entity", e: e, depth: depth + 1, anc: anc });
151	        });
152	      }
153	    }
154	    ROOTS.forEach(function (r) { walk(r, 1, [r.id]); });
155	    return rows;
156	  }
157	
158	  function visibleEntityIds(rows) {
159	    var out = [];
160	    rows.forEach(function (r) { if (r.kind === "entity") out.push(r.e.id); });
161	    return out;
162	  }
163	  function statusCounts() {
164	    var c = { online: 0, maintenance: 0, retired: 0 };
165	    entityById.forEach(function (e) { c[e.status] += 1; });
166	    return c;
167	  }
168	  function selectedEntities() {
169	    var out = [];
170	    state.selected.forEach(function (id) {
171	      var e = entityById.get(id);
172	      if (e) out.push(e);
173	    });
174	    out.sort(function (a, b) { return a.code < b.code ? -1 : 1; });
175	    return out;
176	  }
177	  function groupByPath(list, describe) {
178	    var map = new Map();
179	    list.forEach(function (item) {
180	      var p = item.e ? entityPath(item.e) : describe(item).path;
181	      if (!map.has(p)) map.set(p, []);
182	      map.get(p).push(item);
183	    });
184	    return Array.from(map.entries());
185	  }
186	
187	  /* ---------------- 动作 ---------------- */
188	  var actions = {
189	    setQuery: function (q) { state.query = q; render(); },
190	    setStatusFilter: function (f) { state.statusFilter = f; render(); },
191	    clearFilters: function () { state.query = ""; state.statusFilter = "all"; var i = el("searchInput"); if (i) { i.value = ""; } render(); },
192	    toggleCollapse: function (gid) {
193	      if (state.collapsed.has(gid)) state.collapsed.delete(gid); else state.collapsed.add(gid);
194	      render();
195	    },
196	    toggleEntity: function (id, checked) {
197	      if (checked) state.selected.add(id); else state.selected.delete(id);
198	      state.anchorId = id;
199	      render();
200	    },
201	    // 分组复选框：可见即作用域 —— 只作用于该分组当前渲染可见的下属实体行
202	    // （折叠分支 / 被筛选隐藏的实体不在渲染行中，机制上进不了选择集）
203	    toggleGroupDirect: function (gid, checked) {
204	      var rows = state.lastRows || [];
205	      rows.forEach(function (r) {
206	        if (r.kind === "entity" && r.anc && r.anc.indexOf(gid) >= 0) {
207	          if (checked) state.selected.add(r.e.id); else state.selected.delete(r.e.id);
208	        }
209	      });
210	      render();
211	    },
212	    // 全选可见：只纳入当前渲染的实体行
213	    selectAllVisible: function () {
214	      visibleEntityIds(state.lastRows || []).forEach(function (id) { state.selected.add(id); });
215	      render();
216	    },
217	    clearSelection: function () { state.selected.clear(); render(); },
