237	  /* ------------- 批量操作（预览 → 确认 → 回执 → 可撤销） ------------- */
238	  function modalAffected() {
239	    var m = state.modal;
240	    var sel = selectedEntities();
241	    if (m.kind === "status") {
242	      var changed = sel.filter(function (e) { return e.status !== m.target; });
243	      return { affected: changed, unchanged: sel.length - changed.length };
244	    }
245	    if (m.kind === "move") {
246	      var moved = m.target ? sel.filter(function (e) { return e.groupId !== m.target; }) : [];
247	      return { affected: moved, unchanged: sel.length - moved.length };
248	    }
249	    return { affected: sel, unchanged: 0 };
250	  }
251	
252	  function opLabel() {
253	    var m = state.modal;
254	    if (m.kind === "status") return "批量状态变更 →「" + STATUS[m.target].label + "」";
255	    if (m.kind === "move") return "批量移动归属 →「" + (m.target ? pathTextOfGroup(m.target) : "?") + "」";
256	    return "批量删除";
257	  }
258	
259	  function executeOp() {
260	    var m = state.modal;
261	    if (!m) return;
262	    var aff = modalAffected();
263	    if (m.kind === "move" && !m.target) { state.modal.error = "请选择目标分组"; render(); return; }
264	    if (aff.affected.length === 0) {
265	      state.modal.error = "所选实体均无需变更（0 项受影响），未执行任何操作。";
266	      render();
267	      return;
268	    }
269	    var ids = aff.affected.map(function (e) { return e.id; });
270	    var label = opLabel();
271	
272	    // 快照（单级撤销：如实记录，再次执行将覆盖上一个回执）
273	    var snapshot = {
274	      kind: m.kind,
275	      target: m.target,
276	      label: label,
277	      time: nowTime(),
278	      selectionBefore: Array.from(state.selected),
279	      entitySnaps: aff.affected.map(function (e) { return JSON.parse(JSON.stringify(e)); })
280	    };
281	
282	    aff.affected.forEach(function (e) {
283	      if (m.kind === "status") e.status = m.target;
284	      if (m.kind === "move") e.groupId = m.target;
285	      if (m.kind === "delete") { entityById.delete(e.id); }
286	    });
287	    rebuildGroupIndex();
288	
289	    if (m.kind === "delete") {
290	      ids.forEach(function (id) { state.selected.delete(id); });
291	    }
292	
293	    state.modal = null;
294	    state.lastOpText = "上次操作：" + label.replace("批量", "") + " · " + snapshot.time + " · 影响 " + ids.length + " 项";
295	    state.receipt = {
296	      text: "已影响 " + ids.length + " 项：" + label,
297	      changed: buildChangedList(aff.affected, m),
298	      undo: snapshot,
299	      undone: false
300	    };
301	    render();
302	  }
303	
304	  function buildChangedList(affected, m) {
305	    return affected.map(function (e) {
306	      var item = { id: e.id, name: e.name + " " + e.code, path: entityPath(e) };
307	      if (m.kind === "status") {
308	        // e 已改为新状态；从快照语义记录"→新"
309	        item.delta = STATUS[m.target].label;
310	      } else if (m.kind === "move") {
311	        item.delta = pathTextOfGroup(m.target);
312	      } else {
313	        item.delta = "已删除";
314	      }
315	      return item;
316	    });
317	  }
