319	  function undoOp() {
320	    var r = state.receipt;
321	    if (!r || !r.undo || r.undone) return;
322	    var snap = r.undo;
323	    snap.entitySnaps.forEach(function (s) {
324	      if (!entityById.has(s.id)) { indexEntity(JSON.parse(JSON.stringify(s))); }
325	      else {
326	        var e = entityById.get(s.id);
327	        e.status = s.status;
328	        e.groupId = s.groupId;
329	      }
330	    });
331	    rebuildGroupIndex();
332	    state.selected = new Set(snap.selectionBefore.filter(function (id) { return entityById.has(id); }));
333	    state.lastOpText = "上次操作：" + snap.label.replace("批量", "") + "（已撤销）";
334	    state.receipt = { text: "已撤销：" + snap.label + "，" + snap.entitySnaps.length + " 项已还原。", changed: [], undo: null, undone: true };
335	    render();
336	  }
