617	  /* ---------------- 树表键盘 / 指针交互 ---------------- */
618	  function visibleRowEls() {
619	    return Array.prototype.slice.call(el("treeGrid").querySelectorAll(".trow:not(.thead)"));
620	  }
621	  function moveRowFocus(dir) {
622	    var rows = visibleRowEls();
623	    if (!rows.length) return;
624	    var idx = rows.findIndex(function (r) { return r.getAttribute("data-row") === state.focusRowId; });
625	    var next = idx < 0 ? 0 : Math.min(rows.length - 1, Math.max(0, idx + dir));
626	    state.focusRowId = rows[next].getAttribute("data-row");
627	    applyTabindex(el("treeGrid"));
628	    rows[next].focus();
629	  }
630	  function onGridKeydown(ev) {
631	    var rowEl = ev.target.closest ? ev.target.closest(".trow:not(.thead)") : null;
632	    if (!rowEl) return;
633	    var rowId = rowEl.getAttribute("data-row");
634	    var kind = rowId.charAt(0) === "g" ? "group" : "entity";
635	    var id = rowId.slice(2);
636	
637	    switch (ev.key) {
638	      case "ArrowDown": ev.preventDefault(); moveRowFocus(1); break;
639	      case "ArrowUp": ev.preventDefault(); moveRowFocus(-1); break;
640	      case "Home": ev.preventDefault(); state.focusRowId = visibleRowEls()[0].getAttribute("data-row"); applyTabindex(el("treeGrid")); visibleRowEls()[0].focus(); break;
641	      case "End": { var rs = visibleRowEls(); ev.preventDefault(); state.focusRowId = rs[rs.length - 1].getAttribute("data-row"); applyTabindex(el("treeGrid")); rs[rs.length - 1].focus(); break; }
642	      case "ArrowRight":
643	        if (kind === "group") { ev.preventDefault(); if (state.collapsed.has(id)) actions.toggleCollapse(id); }
644	        break;
645	      case "ArrowLeft":
646	      case "Enter":
647	        if (kind === "group") { ev.preventDefault(); actions.toggleCollapse(id); }
648	        break;
649	      case " ":
650	      case "Spacebar":
651	        if (ev.target.tagName === "INPUT") return; // 复选框原生行为
652	        ev.preventDefault();
653	        if (kind === "entity") {
654	          var e = entityById.get(id);
655	          actions.toggleEntity(id, !state.selected.has(id));
656	          if (state.selected.has(id)) state.anchorId = id;
657	          void e;
658	        } else {
659	          // 分组行空格：等价点击其复选框（可见直接实体全选/取消）
660	          var cb = rowEl.querySelector('input[type="checkbox"]');
661	          if (cb && !cb.disabled) actions.toggleGroupDirect(id, !cb.checked || cb.indeterminate);
662	        }
663	        break;
664	      default: break;
665	    }
666	  }
667	  function onGridClick(ev) {
668	    var rowEl = ev.target.closest(".trow:not(.thead)");
669	    if (!rowEl) return;
670	    var rowId = rowEl.getAttribute("data-row");
671	    state.focusRowId = rowId;
672	    applyTabindex(el("treeGrid"));
673	    if (ev.target.tagName === "INPUT" || ev.target.closest("button")) return;
674	
675	    if (rowId.charAt(0) === "g") {
676	      actions.toggleCollapse(rowId.slice(2));
677	      return;
678	    }
679	    var id = rowId.slice(2);
680	    if (ev.shiftKey && state.anchorId && entityById.has(state.anchorId)) {
681	      // 范围选择：锚点 → 当前行（仅当前可见行；可见即作用域）
682	      var ids = visibleEntityIds(state.lastRows || []);
683	      var a = ids.indexOf(state.anchorId), b = ids.indexOf(id);
684	      if (a >= 0 && b >= 0) {
685	        var lo = Math.min(a, b), hi = Math.max(a, b);
686	        for (var i = lo; i <= hi; i++) state.selected.add(ids[i]);
687	        render();
688	        return;
689	      }
690	    }
691	    state.anchorId = id; // 普通点击只设锚点，不改变选择（防误选）
692	  }
693	
694	  /* ---------------- 渲染：检查器（选择集清单） ---------------- */
695	  function renderInspector() {
696	    var box = el("inspector");
697	    var sel = selectedEntities();
698	    var head = h("div", { class: "insp-head" }, "选择集", h("span", { class: "count" }, String(sel.length)));
699	    if (sel.length === 0) {
700	      box.replaceChildren(
701	        head,
702	        h("div", { class: "insp-empty" },
703	          h("div", { class: "glyph", "aria-hidden": "true" }, "☐"),
704	          h("p", null, h("strong", null, "尚未选择任何实体")),
705	          h("p", null, "勾选左侧行或分组复选框以构建选择集。"),
706	          h("p", null, "折叠分支与被筛选隐藏的实体不会进入选择集——批量操作只作用于下方显式列出的项。")
707	        )
708	      );
709	      return;
710	    }
711	    var byStatus = { online: 0, maintenance: 0, retired: 0 };
712	    sel.forEach(function (e) { byStatus[e.status] += 1; });
713	
714	    var body = h("div", { class: "insp-body" });
715	    groupByPath(sel, function (x) { return { path: entityPath(x) }; }).forEach(function (pair) {
716	      body.appendChild(h("div", { class: "insp-path" },
717	        h("span", null, pair[0]), h("span", { class: "rule" }), h("span", null, pair[1].length + " 项")));
718	      pair[1].forEach(function (e) {
719	        body.appendChild(h("div", { class: "insp-item" },
720	          h("span", { class: "st-badge " + STATUS[e.status].cls }, STATUS[e.status].label),
721	          h("span", { class: "nm", title: e.name }, e.name),
722	          h("span", { class: "cd" }, e.code),
723	          h("button", {
724	            class: "rm", title: "从选择集移除 " + e.name, "aria-label": "从选择集移除 " + e.name,
725	            onclick: function () { actions.removeSelected(e.id); }
726	          }, "×")
727	        ));
728	      });
729	    });
730	
731	    box.replaceChildren(
732	      head,
733	      h("div", { class: "insp-stats" },
734	        "在线 ", h("span", { class: "num" }, String(byStatus.online)),
735	        " · 维护中 ", h("span", { class: "num" }, String(byStatus.maintenance)),
736	        " · 停用 ", h("span", { class: "num" }, String(byStatus.retired))
737	      ),
738	      body,
739	      h("div", { class: "insp-foot" },
740	        h("span", { class: "hint" }, "批量操作仅作用于以上显式勾选的 " + sel.length + " 项"),
741	        h("button", { class: "btn quiet", onclick: function () { actions.clearSelection(); } }, "清空")
742	      )
