837	
838	    // 显式错误状态：目标分组与全部所选归属相同 → 0 项可变更，阻止执行
839	    if (m.kind === "move" && m.target && aff.affected.length === 0 && !m.error) {
840	      body.appendChild(h("div", { class: "dlg-error", role: "alert" },
841	        "所选 " + selN + " 项均已属于「" + pathTextOfGroup(m.target) + "」，无可变更项（影响 0 项）。请更换目标分组或取消。"));
842	    }
843	
844	    if (m.kind === "status" && aff.unchanged > 0) {
845	      body.appendChild(h("div", { class: "dlg-meta", style: "margin:0 0 8px" },
846	        "另 " + aff.unchanged + " 项已处于「" + STATUS[m.target].label + "」，不会重复计入影响。"));
847	    }
848	    if (m.kind === "move" && !m.target) {
849	      body.appendChild(h("div", { class: "dlg-meta", style: "margin:0 0 8px" }, "选择目标分组后，此处将按归属路径列出受影响实体。"));
850	    }
851	
852	    if (aff.affected.length) {
853	      var describe = function (e) {
854	        return {
855	          path: entityPath(e),
856	          name: e.name + " " + e.code,
857	          delta: m.kind === "status" ? STATUS[e.status].label + " → " + STATUS[m.target].label
858	            : m.kind === "move" ? entityPath(e) + " → " + pathTextOfGroup(m.target)
859	            : STATUS[e.status].label + " → 删除"
860	        };
861	      };
862	      groupByPath(aff.affected, describe).forEach(function (pair) {
863	        body.appendChild(h("div", { class: "pv-group" },
864	          h("span", null, pair[0]), h("span", { class: "rule" }),
865	          h("span", { class: "n" }, pair[1].length + " 项")));
866	        pair[1].forEach(function (e) {
867	          var d = describe(e);
868	          body.appendChild(h("div", { class: "pv-item" },
869	            h("span", { class: "nm" }, e.name + " " + e.code),
870	            h("span", { class: "delta " + (danger ? "to-danger" : "to") },
871	              m.kind === "move" ? "→ " + pathTextOfGroup(m.target) : d.delta)
872	          ));
873	        });
874	      });
875	    }
876	
877	    var confirmLabel = "确认执行（影响 " + aff.affected.length + " 项）";
878	    var dialog = h("div", {
879	      class: "dialog" + (danger ? " danger" : ""), role: "dialog", "aria-modal": "true",
880	      "aria-labelledby": "dlgTitle", tabindex: "-1"
881	    },
882	      h("div", { class: "dlg-head" },
883	        h("h2", { class: "dlg-title", id: "dlgTitle" }, title),
884	        h("div", { class: "dlg-meta" },
885	          "操作：", h("strong", null, opLabel()),
886	          h("span", null, "　·　选择集 ", h("strong", null, String(selN)), " 项"),
887	          m.kind !== "move" || m.target
888	            ? h("span", null, "　·　受影响 ", h("strong", null, String(aff.affected.length)), " 项")
889	            : null,
890	          danger && aff.affected.length
891	            ? h("span", { class: "warn-note" }, "　·　删除可通过回执中的「撤销」一步还原")
892	            : null
893	        )
894	      ),
895	      body,
896	      h("div", { class: "dlg-foot" },
897	        h("span", { class: "note" }, "仅作用于显式勾选的选择集；取消不产生任何变更。"),
898	        h("span", { class: "spacer" }),
899	        h("button", { class: "btn", onclick: function () { actions.closeModal(); } }, "取消"),
900	        h("button", {
901	          class: "btn " + (danger ? "danger" : "primary"),
902	          disabled: aff.affected.length === 0 || (m.kind === "move" && !m.target),
903	          onclick: function () { actions.confirmModal(); }
904	        }, confirmLabel)
905	      )
906	    );
907	
908	    var overlay = h("div", {
909	      class: "overlay",
910	      onclick: function (ev) { if (ev.target === overlay) actions.closeModal(); }
911	    }, dialog);
912	    root.appendChild(overlay);
913	
914	    overlay.addEventListener("keydown", function (ev) { if (ev.key === "Escape") actions.closeModal(); });
915	    // 焦点进入对话框
916	    var focusTarget = dialog.querySelector("#moveTarget") ||
917	      dialog.querySelector(".btn.primary, .btn.danger");
918	    if (focusTarget) focusTarget.focus(); else dialog.focus();
919	  }
920	
921	  /* ---------------- 渲染总入口 ---------------- */
922	  function render() {
923	    if (state.phase === "loading") { renderLoading(); return; }
924	    renderToolbarMenu();
925	    renderTree();      // 先树（得到 visibleEntityCount）
926	    renderToolbar();
927	    renderInspector();
928	    renderReceipt();
929	    renderError();
930	    renderFooter();
931	    renderModal();
932	  }
933	  function renderLoading() {
934	    // 状态机完备性保留：数据随页面内联，ready 同步到达，此分支不作为可测状态出现
935	    el("app").replaceChildren(h("div", { class: "skeleton" },
936	      h("div", { class: "bar", style: "width:40%" }),
937	      h("div", { class: "bar", style: "width:70%" }),
938	      h("div", { class: "bar", style: "width:55%" })));
939	  }
940	
941	  /* ---------------- 全局事件 ---------------- */
942	  document.addEventListener("click", function (ev) {
943	    if (state.menuOpen && !ev.target.closest(".menu-anchor")) actions.toggleMenu(false);
944	  }, true);
945	  document.addEventListener("keydown", function (ev) {
946	    if (ev.key === "Escape" && state.menuOpen) actions.toggleMenu(false);
947	  });
948	
949	  /* ---------------- 测试钩子（浏览器验证用，不影响 UI） ---------------- */
950	  window.__REGISTRY__ = {
951	    state: state,
952	    buildRows: buildRows,
953	    visibleEntityIds: function () { return visibleEntityIds(state.lastRows || []); },
954	    counts: function () { return { total: entityById.size, selected: state.selected.size, visible: state.visibleEntityCount }; },
955	    entity: function (id) { return entityById.get(id); },
956	    entitiesOfGroup: directEntities,
957	    pathOf: pathTextOfGroup
958	  };
959	
