      h("main", { class: "layout" },
        h("section", { class: "tree-panel", "aria-label": "层级分组树表" },
          h("div", { class: "panel-cap" },
            "层级分组树表",
            h("span", { class: "hint" }, "勾选仅作用于当前可见的下属实体行；折叠分支不会被批量选中"),
            h("span", { class: "rule" })
          ),
          h("div", { class: "tree-scroll" },
            h("div", { class: "treegrid", id: "treeGrid", role: "treegrid",
              "aria-label": "实体层级列表",
