      R.entitiesOfGroup(gid).forEach(function (e) { if (!seen.has(e.id)) { seen.add(e.id); fn(e); } });
      document; // noop
      var subs = childGroups(gid);
      subs.forEach(function (s) { walkGroup(s, fn, seen); });
    }
    function childGroups(gid) {
      // 通过 __REGISTRY__.pathOf 不可枚举子分组；改用 DOM 之外的数据：
      return (window.__REGISTRY__._groups && window.__REGISTRY__._groups[gid]) || [];
    }
  }

  /* ---------- 执行 ---------- */
  try {
    stage0();
    var seq = [stage1, stage2, stage3, stage4, stage5, stage6, stage7, stage8];
    for (var i = 1; i <= STAGE && i <= seq.length; i++) seq[i - 1]();
  } catch (e) {
    log("exception: " + e.message, false, (e.stack || "").split("\n")[1] || "");
  }
  // 阶段标记进入 DOM，便于截图核对
  var tag = document.createElement("div");
  tag.id = "selftest-stage";
  tag.textContent = "SELFTEST stage=" + STAGE + " checks=" + LOG.length + " failed=" + LOG.filter(function (l) { return !l.pass; }).length;
