/* =====================================================================
 * 实体台账管理台 — 设计令牌与样式
 * 密度取向 compact（H-13 Structured Density）：结构承载密度，行高 ~30px
 * ===================================================================== */

:root {
  --bg: #f5f6f8;
  --panel: #ffffff;
  --line: #e3e6ea;
  --line-strong: #cfd6dd;
  --ink: #1c2530;
  --ink-2: #51606f;
  --ink-3: #8a97a5;
  --accent: #2f5fe0;
  --accent-ink: #1e46b8;
  --accent-weak: #eaf0ff;
  --sel-row: #f0f5ff;
  --ok: #178649;      --ok-bg: #e8f6ee;
  --warn: #b25e09;    --warn-bg: #fdf3e3;
  --mut: #6b7683;     --mut-bg: #eff1f4;
  --danger: #c0362c;  --danger-bg: #fdeceb;
  --radius: 6px;
  --row-h: 30px;
  --font: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --mono: ui-monospace, "Cascadia Mono", Consolas, monospace;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 13px;
  line-height: 1.45;
  color: var(--ink);
  background: var(--bg);
}
button { font: inherit; cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .45; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 3px; }

#app { height: 100vh; display: flex; flex-direction: column; overflow: hidden; }

/* ---------- 头部品牌条 ---------- */
.site-header {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 14px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  flex: none;
}
.brand-mark {
  width: 22px; height: 22px; border-radius: 6px;
  background: linear-gradient(135deg, var(--accent), #6a8bf0);
  color: #fff; font-weight: 700; font-size: 11px;
  display: inline-flex; align-items: center; justify-content: center;
  letter-spacing: .5px;
}
.site-header h1 { font-size: 14px; margin: 0; font-weight: 600; }
.site-header .sub { color: var(--ink-3); font-size: 12px; }
.badge {
  font-size: 11px; padding: 1px 8px; border-radius: 999px;
  background: var(--accent-weak); color: var(--accent-ink);
  border: 1px solid #d4e0ff;
}

/* ---------- 工具栏（persistent_command_bar） ---------- */
.toolbar {
  flex: none;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  padding: 8px 14px;
  display: flex; flex-direction: column; gap: 8px;
}
.toolbar-row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

.search { position: relative; }
.search input {
  width: 240px; height: 28px;
  border: 1px solid var(--line-strong); border-radius: var(--radius);
  padding: 0 26px 0 28px; font: inherit; color: var(--ink);
  background: #fff;
}
.search input::placeholder { color: var(--ink-3); }
.search .icon {
  position: absolute; left: 9px; top: 50%; transform: translateY(-50%);
  color: var(--ink-3); font-size: 12px; pointer-events: none;
}
.search .clear {
  position: absolute; right: 4px; top: 50%; transform: translateY(-50%);
  border: 0; background: transparent; color: var(--ink-3);
  width: 20px; height: 20px; border-radius: 4px; font-size: 13px;
  display: none;
}
.search.has-value .clear { display: inline-flex; align-items: center; justify-content: center; }
.search .clear:hover { background: var(--mut-bg); color: var(--ink); }

.seg { display: inline-flex; border: 1px solid var(--line-strong); border-radius: var(--radius); overflow: hidden; }
.seg button {
  border: 0; background: #fff; padding: 4px 10px;
  color: var(--ink-2); border-right: 1px solid var(--line);
}
.seg button:last-child { border-right: 0; }
.seg button .n { color: var(--ink-3); font-variant-numeric: tabular-nums; margin-left: 3px; }
.seg button.active { background: var(--accent-weak); color: var(--accent-ink); font-weight: 600; }
.seg button.active .n { color: var(--accent-ink); }

.scope { margin-left: auto; color: var(--ink-2); font-size: 12px; display: inline-flex; gap: 6px; align-items: center; }
.scope .num { font-variant-numeric: tabular-nums; }
.scope .sep { color: var(--line-strong); }
.scope strong { color: var(--accent-ink); font-variant-numeric: tabular-nums; }

.btn {
  height: 28px; padding: 0 11px;
  border: 1px solid var(--line-strong); border-radius: var(--radius);
  background: #fff; color: var(--ink); font-size: 12.5px;
  display: inline-flex; align-items: center; gap: 5px;
}
.btn:hover:not(:disabled) { background: #f6f8fa; border-color: #b9c2cc; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn.primary:hover:not(:disabled) { background: var(--accent-ink); }
.btn.danger { color: var(--danger); border-color: #eac6c2; }
.btn.danger:hover:not(:disabled) { background: var(--danger-bg); }
.btn.quiet { border-color: transparent; background: transparent; color: var(--ink-2); }
.btn.quiet:hover:not(:disabled) { background: var(--mut-bg); border-color: transparent; }
.btn.caret::after { content: "▾"; font-size: 10px; color: inherit; opacity: .7; }
.toolbar .actions { display: flex; gap: 6px; align-items: center; }
.vr { width: 1px; height: 18px; background: var(--line); }
.sel-chip { font-size: 12px; color: var(--ink-2); }
.sel-chip strong { color: var(--accent-ink); font-variant-numeric: tabular-nums; }

/* 菜单（变更状态下拉） */
.menu-anchor { position: relative; }
.menu {
  position: absolute; top: 32px; left: 0; z-index: 60;
  min-width: 168px; padding: 4px;
  background: #fff; border: 1px solid var(--line-strong); border-radius: 8px;
  box-shadow: 0 8px 24px rgba(16, 24, 40, .14);
}
.menu button {
  display: flex; width: 100%; align-items: center; gap: 8px;
  border: 0; background: transparent; padding: 6px 8px; border-radius: 5px;
  text-align: left;
}
.menu button:hover { background: var(--mut-bg); }

/* ---------- 回执条（execution_receipt） ---------- */
.receipt {
  flex: none; margin: 8px 14px 0;
  border: 1px solid #cde8d8; border-left: 3px solid var(--ok);
  background: #f2fbf6; border-radius: var(--radius);
  padding: 7px 10px; display: flex; align-items: center; gap: 10px;
  font-size: 12.5px;
}
.receipt .tick { color: var(--ok); font-weight: 700; }
.receipt strong { font-variant-numeric: tabular-nums; }
.receipt.undone { border-color: #d8dde3; border-left-color: var(--ink-3); background: #f6f7f9; }
.receipt .detail { margin-left: auto; display: flex; gap: 6px; align-items: center; }
.receipt details { font-size: 12px; }
.receipt details summary { cursor: pointer; color: var(--ink-2); user-select: none; }
.receipt .changed-list {
  margin: 6px 0 0; padding: 6px 10px; max-height: 160px; overflow: auto;
  background: #fff; border: 1px solid var(--line); border-radius: 5px;
  color: var(--ink-2); font-size: 12px;
}
.receipt .changed-list div { padding: 1px 0; }

/* ---------- 错误横幅 ---------- */
.error-banner {
  flex: none; margin: 8px 14px 0;
  border: 1px solid #efc7c3; border-left: 3px solid var(--danger);
  background: var(--danger-bg); color: var(--danger);
  border-radius: var(--radius); padding: 7px 10px;
  display: flex; align-items: center; gap: 8px; font-size: 12.5px;
}
.error-banner .x {
  margin-left: auto; border: 0; background: transparent; color: inherit;
  width: 20px; height: 20px; border-radius: 4px;
}
.error-banner .x:hover { background: rgba(0,0,0,.06); }

/* ---------- 主布局 ---------- */
.layout { flex: 1; display: flex; min-height: 0; padding: 10px 14px; gap: 10px; }
.tree-panel {
  flex: 1; min-width: 0; display: flex; flex-direction: column;
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  overflow: hidden;
}
.panel-cap {
  flex: none; padding: 7px 12px; font-size: 11px; font-weight: 600;
  letter-spacing: .08em; color: var(--ink-3); text-transform: uppercase;
  border-bottom: 1px solid var(--line);
  display: flex; align-items: center; gap: 8px;
}
.panel-cap .hint { font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--ink-3); }
.panel-cap .rule { flex: 1; }

/* ---------- 树表（dominant_workspace · treegrid） ---------- */
.tree-scroll { flex: 1; overflow: auto; }
.treegrid { min-width: 720px; }
.trow {
  display: grid;
  grid-template-columns: 34px minmax(260px, 1.2fr) 96px minmax(220px, 1fr);
  align-items: center;
  min-height: var(--row-h);
  border-bottom: 1px solid #f0f2f5;
  font-size: 12.5px;
}
.trow.thead {
  position: sticky; top: 0; z-index: 5;
  background: #fafbfc; border-bottom: 1px solid var(--line);
  color: var(--ink-3); font-size: 11px; font-weight: 600; letter-spacing: .05em;
  min-height: 28px;
}
.trow.thead > span { padding: 0 8px; }
.trow:hover { background: #f7f9fb; }
.trow.selected { background: var(--sel-row); box-shadow: inset 2px 0 0 var(--accent); }
.trow.group-row { background: #f8fafc; font-weight: 600; }
.trow.group-row:hover { background: #f1f4f8; }
.trow.entity-row { font-weight: 400; }

.c-check { display: flex; align-items: center; justify-content: center; }
.c-check input[type="checkbox"] { width: 14px; height: 14px; accent-color: var(--accent); margin: 0; }

.c-name { padding: 0 8px; display: flex; align-items: center; gap: 6px; min-width: 0; }
.c-name .indent { flex: none; }
.caret {
  flex: none; width: 18px; height: 18px; border: 0; background: transparent;
  color: var(--ink-3); border-radius: 4px; display: inline-flex; align-items: center; justify-content: center;
  font-size: 10px; transition: transform .12s ease;
}
.caret:hover { background: #e8ecf1; color: var(--ink); }
.caret.open { transform: rotate(90deg); }
.caret.leaf { visibility: hidden; }
.c-name .name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.c-name .code { color: var(--ink-3); font-family: var(--mono); font-size: 11px; flex: none; }
.g-count {
  flex: none; font-size: 10.5px; font-weight: 500; color: var(--ink-3);
  border: 1px solid var(--line); border-radius: 999px; padding: 0 7px;
  background: #fff; font-variant-numeric: tabular-nums;
}

.st-badge {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 11px; padding: 1px 8px; border-radius: 999px; width: fit-content;
}
.st-badge::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.st-online      { color: var(--ok);   background: var(--ok-bg); }
.st-maintenance { color: var(--warn); background: var(--warn-bg); }
.st-retired     { color: var(--mut);  background: var(--mut-bg); }
.c-status { padding: 0 8px; }

.c-path { padding: 0 8px; color: var(--ink-3); font-size: 11.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.empty-state { padding: 42px 20px; text-align: center; color: var(--ink-3); }
.empty-state .glyph { font-size: 22px; margin-bottom: 6px; }
.empty-state .btn { margin-top: 10px; }

/* ---------- 检查器（contextual_inspector） ---------- */
.inspector {
  flex: none; width: 300px; display: flex; flex-direction: column;
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  overflow: hidden;
}
.insp-head {
  flex: none; padding: 8px 12px; border-bottom: 1px solid var(--line);
  display: flex; align-items: center; gap: 8px; font-weight: 600;
}
.insp-head .count {
  background: var(--accent); color: #fff; border-radius: 999px;
  min-width: 20px; height: 20px; padding: 0 6px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 11.5px; font-variant-numeric: tabular-nums;
}
.insp-stats { flex: none; padding: 6px 12px; color: var(--ink-2); font-size: 12px; border-bottom: 1px solid #f0f2f5; }
.insp-stats .num { font-variant-numeric: tabular-nums; }
.insp-body { flex: 1; overflow: auto; padding: 8px 12px; }
.insp-path {
  display: flex; align-items: center; gap: 6px;
  margin: 10px 0 4px; color: var(--ink-3); font-size: 11px;
}
.insp-path:first-child { margin-top: 2px; }
.insp-path .rule { flex: 1; height: 1px; background: var(--line); }
.insp-item {
  display: flex; align-items: center; gap: 6px;
  padding: 3px 4px; border-radius: 5px;
}
.insp-item:hover { background: #f6f8fa; }
.insp-item .nm { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.insp-item .cd { color: var(--ink-3); font-family: var(--mono); font-size: 10.5px; flex: none; }
.insp-item .rm {
  flex: none; width: 18px; height: 18px; border: 0; border-radius: 4px;
  background: transparent; color: var(--ink-3); font-size: 12px;
  display: inline-flex; align-items: center; justify-content: center;
}
.insp-item .rm:hover { background: var(--danger-bg); color: var(--danger); }
.insp-empty { padding: 36px 14px; text-align: center; color: var(--ink-3); }
.insp-empty .glyph { font-size: 20px; margin-bottom: 8px; }
.insp-empty p { margin: 4px 0; font-size: 12px; }
.insp-foot {
  flex: none; padding: 8px 12px; border-top: 1px solid var(--line);
  display: flex; align-items: center; gap: 8px;
}
.insp-foot .hint { flex: 1; color: var(--ink-3); font-size: 11px; }

/* ---------- 状态条（orientation_footer） ---------- */
.status-bar {
  flex: none; display: flex; align-items: center; gap: 14px;
  padding: 6px 16px; border-top: 1px solid var(--line);
  background: var(--panel); color: var(--ink-2); font-size: 12px;
}
.status-bar .num { font-variant-numeric: tabular-nums; }
.status-bar .dot { color: var(--line-strong); }
.status-bar .last { color: var(--ink-2); }
.status-bar .mem { margin-left: auto; color: var(--ink-3); }
.status-bar .undo-link {
  border: 0; background: transparent; color: var(--accent-ink);
  text-decoration: underline; padding: 0; font-size: 12px;
}

/* ---------- 模态（confirmation_modal） ---------- */
.overlay {
  position: fixed; inset: 0; z-index: 100;
  background: rgba(18, 24, 33, .44);
  display: flex; align-items: center; justify-content: center;
}
.dialog {
  width: min(560px, calc(100vw - 48px));
  max-height: min(640px, calc(100vh - 64px));
  display: flex; flex-direction: column;
  background: #fff; border-radius: 10px;
  box-shadow: 0 20px 50px rgba(16, 24, 40, .28);
}
.dialog.danger .dlg-title { color: var(--danger); }
.dlg-head { flex: none; padding: 14px 16px 0; }
.dlg-title { margin: 0; font-size: 15px; }
.dlg-meta { margin-top: 6px; color: var(--ink-2); font-size: 12.5px; }
.dlg-meta strong { font-variant-numeric: tabular-nums; }
.dlg-meta .warn-note { color: var(--warn); }
.dlg-body { flex: 1; overflow: auto; padding: 10px 16px; }
.dlg-field { margin: 4px 0 10px; }
.dlg-field label { display: block; font-size: 12px; color: var(--ink-2); margin-bottom: 4px; }
.dlg-field select {
  width: 100%; height: 30px; font: inherit;
  border: 1px solid var(--line-strong); border-radius: var(--radius);
  padding: 0 6px; background: #fff; color: var(--ink);
}
.dlg-error {
  border: 1px solid #efc7c3; background: var(--danger-bg); color: var(--danger);
  border-radius: var(--radius); padding: 7px 10px; font-size: 12.5px; margin: 4px 0 8px;
}
.pv-group { margin: 8px 0 2px; color: var(--ink-3); font-size: 11px; display: flex; align-items: center; gap: 6px; }
.pv-group .rule { flex: 1; height: 1px; background: var(--line); }
.pv-group .n { font-variant-numeric: tabular-nums; }
.pv-item { display: flex; gap: 8px; padding: 2px 0 2px 10px; font-size: 12.5px; }
.pv-item .nm { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pv-item .delta { flex: none; color: var(--ink-2); font-size: 11.5px; }
.pv-item .delta .arr { color: var(--ink-3); margin: 0 3px; }
.pv-item .delta.to { color: var(--accent-ink); font-weight: 600; }
.pv-item .delta.to-danger { color: var(--danger); font-weight: 600; }
.dlg-foot {
  flex: none; display: flex; align-items: center; gap: 8px;
  padding: 12px 16px; border-top: 1px solid var(--line);
}
.dlg-foot .spacer { flex: 1; }
.dlg-foot .note { color: var(--ink-3); font-size: 11.5px; }

/* 加载骨架（状态机完备性保留；本应用数据内联，ready 同步到达，不会出现可测加载态） */
.skeleton { padding: 30px 20px; color: var(--ink-3); }
.skeleton .bar { height: 12px; border-radius: 6px; background: #eef0f3; margin: 8px 0; animation: pulse 1.2s ease-in-out infinite; }
@keyframes pulse { 50% { opacity: .55; } }

/* 窄屏兜底（桌面上下文，不承诺移动布局） */
@media (max-width: 980px) {
  .inspector { width: 240px; }
  .c-path { display: none; }
  .trow { grid-template-columns: 34px minmax(220px, 1fr) 96px; }
}

/* =====================================================================
 * selftest.js — 浏览器自证场景（仅 ?selftest=1 时激活；正常打开零影响）
 *
 * 通过真实 DOM 事件（click / input / change / keydown）驱动应用自身交互，
 * 逐阶段断言并把结果渲染进 #selftestPanel 与 #selftest-json，
 * 供无头浏览器截图与 DOM dump 作为运行证据。
 * 阶段语义：stage=N 表示从全新加载起顺序执行阶段 1..N（数据确定性种子）。
 * ===================================================================== */
(function () {
  "use strict";
  if (location.search.indexOf("selftest=1") < 0) return;

  var STAGE = Math.max(0, parseInt((location.search.match(/stage=(\d+)/) || [])[1] || "0", 10));
  var LOG = [];

  window.addEventListener("error", function (e) {
    LOG.push({ stage: STAGE, name: "jserror:" + e.message, pass: false, got: String(e.filename + ":" + e.lineno) });
    flush();
  });

  function log(name, pass, got) { LOG.push({ stage: STAGE, name: name, pass: !!pass, got: String(got) }); }
  function assertEq(name, got, want) { log(name + " [want=" + want + "]", got === want, "got=" + got); }
  function assertTrue(name, got) { log(name, !!got, "got=" + got); }

  function flush() {
    var panel = document.getElementById("selftestPanel");
    if (!panel) {
      panel = document.createElement("div");
      panel.id = "selftestPanel";
      document.body.appendChild(panel);
      panel.appendChild(document.createElement("div")).id = "selftest-lines";
      var pre = document.createElement("pre");
      pre.id = "selftest-json";
      panel.appendChild(pre);
    }
    var lines = panel.querySelector("#selftest-lines");
    lines.replaceChildren();
    LOG.forEach(function (l) {
      var d = document.createElement("div");
      d.textContent = (l.pass ? "✓ " : "✗ ") + "S" + l.stage + " " + l.name + " — " + l.got;
      d.style.color = l.pass ? "#0a7a3d" : "#c0362c";
      lines.appendChild(d);
    });
    panel.querySelector("#selftest-json").textContent = JSON.stringify(LOG);
  }

  /* ---------- 驱动工具（全部走真实 DOM 事件） ---------- */
  function groupRowByName(text) {
    var rows = document.querySelectorAll("#treeGrid .trow.group-row");
    for (var i = 0; i < rows.length; i++) {
      var n = rows[i].querySelector(".c-name .name");
      if (n && n.textContent === text) return rows[i];
    }
    return null;
  }
  function entityRow(id) {
    return document.querySelector('#treeGrid [data-row="e:' + id + '"]');
  }
  function checkGroup(name) {
    var r = groupRowByName(name);
    var cb = r && r.querySelector('input[type="checkbox"]');
    if (cb && !cb.disabled) cb.click();
    return cb;
  }
  function setFilter(f) { document.querySelector('#statusSeg button[data-filter="' + f + '"]').click(); }
  function setQuery(q) {
    var i = document.getElementById("searchInput");
    i.value = q;
    i.dispatchEvent(new Event("input", { bubbles: true }));
  }
  function dialogBtn(text) {
    var btns = document.querySelectorAll("#modalRoot .dialog button");
    for (var i = 0; i < btns.length; i++) {
      if (btns[i].textContent.indexOf(text) >= 0) return btns[i];
    }
    return null;
  }
  function receiptBtn(text) {
    var btns = document.querySelectorAll("#receiptSlot button");
    for (var i = 0; i < btns.length; i++) {
      if (btns[i].textContent.indexOf(text) >= 0) return btns[i];
    }
    return null;
  }
  function counts() { return window.__REGISTRY__.counts(); }
  function entitiesByGroup(gid) { return window.__REGISTRY__.entitiesOfGroup(gid).map(function (e) { return e.id; }); }
  function selectedIds() { return Array.from(window.__REGISTRY__.state.selected); }

  /* ---------- 阶段（顺序累积执行） ---------- */
  var R = window.__REGISTRY__;

  function stage0() {
    assertEq("S0 total", counts().total, 160);
    assertEq("S0 selected", counts().selected, 0);
    assertEq("S0 visible", counts().visible, 160);
    assertTrue("S0 tree rows rendered", document.querySelectorAll("#treeGrid .trow").length > 100);
    assertEq("S0 phase ready", R.state.phase, "ready");
    assertTrue("S0 inspector empty-state", !!document.querySelector("#inspector .insp-empty"));
    assertTrue("S0 receipt absent", !document.querySelector("#receiptSlot .receipt"));
  }

  function stage1() {
    // 折叠「水务计量」（6 实体）→ 勾选系统「能耗计量系统」
    var wtr = groupRowByName("水务计量");
    wtr.querySelector("button.caret").click();
    assertEq("S1 visible after collapse", counts().visible, 154);
    var cb = checkGroup("能耗计量系统");
    assertEq("S1 selected (only rendered descendants)", counts().selected, 12);
    var bad = selectedIds().filter(function (id) { return R.entity(id).groupId === "sg-hq-ene-wtr"; });
    assertEq("S1 collapsed-unit entities selected", bad.length, 0);
    assertTrue("S1 system checkbox indeterminate", !!cb && cb.indeterminate === true);
    assertEq("S1 inspector items", document.querySelectorAll("#inspector .insp-item").length, 12);
  }

  var retiredCount = 0;

  function stage2() {
    document.getElementById("btnClearSel").click();
    setFilter("retired");
    document.getElementById("btnSelectAll").click();
    assertEq("S2 selected == visible (retired scope)", counts().selected, counts().visible);
    assertTrue("S2 visible < total", counts().visible < counts().total);
    assertEq("S2 scope indicator shows retired only", document.getElementById("scope").textContent.indexOf("可见 " + counts().visible) >= 0, true);
  }

  function stage3() {
    var maintBefore = statusCount("maintenance");
    retiredCount = counts().selected; // = stage2 选中的全部停用实体
    setFilter("all");
    document.getElementById("btnStatus").click();
    var menuBtns = document.querySelectorAll("#menuSlot .menu button");
    var target = null;
    menuBtns.forEach(function (b) { if (b.textContent.indexOf("维护中") >= 0) target = b; });
    target.click();
    assertTrue("S3 preview dialog open", !!document.querySelector("#modalRoot .dialog"));
    var confirmBtn = dialogBtn("确认执行");
    assertEq("S3 preview affected count", confirmBtn.textContent, "确认执行（影响 " + retiredCount + " 项）");
    confirmBtn.click();
    assertTrue("S3 receipt shown", !!document.querySelector("#receiptSlot .receipt"));
    assertTrue("S3 receipt text", document.querySelector("#receiptSlot .receipt").textContent.indexOf("已影响 " + retiredCount + " 项") >= 0);
    assertEq("S3 maintenance after", statusCount("maintenance"), maintBefore + retiredCount);
    window.__S3 = { maintBefore: maintBefore, retired: retiredCount };
  }

  function stage4() {
    var before = window.__S3 || { maintBefore: statusCount("maintenance"), retired: 0 };
    receiptBtn("撤销此次操作").click();
    assertTrue("S4 receipt undone text", document.querySelector("#receiptSlot .receipt").textContent.indexOf("已撤销") >= 0);
    assertEq("S4 maintenance restored", statusCount("maintenance"), before.maintBefore);
    assertEq("S4 total intact", counts().total, 160);
  }

  function stage5() {
    document.getElementById("btnClearSel").click();
    checkGroup("温度监测");
    assertEq("S5 unit select count", counts().selected, 12);
    document.getElementById("btnMove").click();
    var sel = document.getElementById("moveTarget");
    // 5a: 目标 = 当前归属 → 显式 0 项错误状态
    sel.value = "sg-hq-env-temp";
    sel.dispatchEvent(new Event("change", { bubbles: true }));
    var err = document.querySelector("#modalRoot .dlg-error");
    assertTrue("S5 zero-effect error visible", !!err && err.textContent.indexOf("影响 0 项") >= 0);
    assertTrue("S5 confirm disabled at 0", dialogBtn("确认执行").disabled);
    // 5b: 有效目标 → 预览 12 项，取消保持选择
    sel.value = "sg-hq-env-hum";
    sel.dispatchEvent(new Event("change", { bubbles: true }));
    assertEq("S5 error cleared", !!document.querySelector("#modalRoot .dlg-error"), false);
    assertEq("S5 preview affected 12", dialogBtn("确认执行").textContent, "确认执行（影响 12 项）");
    dialogBtn("取消").click();
    assertEq("S5 selection preserved after cancel", counts().selected, 12);
    var still = entitiesByGroup("sg-hq-env-temp").length;
    assertEq("S5 no move executed", still, 12);
  }

  function stage6() {
    document.getElementById("btnClearSel").click();
    entityRow("E001").querySelector('input[type="checkbox"]').click();
    entityRow("E002").querySelector('input[type="checkbox"]').click();
    assertEq("S6 picked 2", counts().selected, 2);
    document.getElementById("btnDelete").click();
    dialogBtn("确认执行").click();
    assertEq("S6 total after delete", counts().total, 158);
    assertTrue("S6 receipt", document.querySelector("#receiptSlot .receipt").textContent.indexOf("已影响 2 项") >= 0);
    receiptBtn("撤销此次操作").click();
    assertEq("S6 total restored", counts().total, 160);
    assertTrue("S6 E001 back", !!window.__REGISTRY__.entity("E001"));
  }

  function stage7() {
    document.getElementById("btnClearSel").click();
    var rows = document.querySelectorAll("#treeGrid .trow.entity-row");
    var first = rows[0];
    first.focus();
    first.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true }));
    var second = document.activeElement;
    assertTrue("S7 focus moved", second && second.closest && !!second.closest("#treeGrid"));
    second.dispatchEvent(new KeyboardEvent("keydown", { key: " ", bubbles: true }));
    assertEq("S7 space selects", counts().selected, 1);
    var rowId = second.getAttribute("data-row");
    assertEq("S7 selected is focused row", selectedIds()[0], rowId.slice(2));
  }

  function stage8() {
    setQuery("zzzz不存在");
    assertEq("S8 visible 0", counts().visible, 0);
    var empty = document.querySelector("#treeGrid .empty-state");
    assertTrue("S8 empty-state text", !!empty && empty.textContent.indexOf("无匹配实体") >= 0);
    // 清除筛选
    var btns = document.querySelectorAll("#treeGrid .empty-state button");
    btns[0].click();
    assertEq("S8 rows restored", counts().visible, 160);
  }

  function statusCount(st) {
    return window.__REGISTRY__.allEntities().filter(function (e) { return e.status === st; }).length;
  }

  /* ---------- 执行 ---------- */
  try {
    stage0();
    var seq = [stage1, stage2, stage3, stage4, stage5, stage6, stage7, stage8];
    for (var i = 1; i <= STAGE && i <= seq.length; i++) seq[i - 1]();
  } catch (e) {
    log("exception: " + e.message, false, (e.stack || "").split("\n")[1] || "");
  }
  // 阶段标记进入 DOM，便于截图核对
  var tag = document.createElement("div");
  tag.id = "selftest-stage";
  tag.textContent = "SELFTEST stage=" + STAGE + " checks=" + LOG.length + " failed=" + LOG.filter(function (l) { return !l.pass; }).length;
  document.body.appendChild(tag);
  flush();
})();

