2	import { DEFAULT_LEGACY_POLICY, GATE_PHASE, NEXT_TOOL_BY_GATE, normalizeCompletedGates } from "./lifecycle-policy.js";
3	
4	export const DESIGN_OPERATIONS = [
5	  "design_frame",
6	  "design_context",
7	  "design_route",
8	  "design_inspect",
9	  "design_decide",
10	  "design_sdir",
11	  "design_reconcile",
12	  "design_prepare_implementation",
13	  "design_validate",
14	] as const;
15	
16	export type DesignOperation = (typeof DESIGN_OPERATIONS)[number];
17	
18	const OPERATION_GATES: Record<DesignOperation, GateName[]> = {
19	  design_frame: ["understanding", "framing", "intent_lite"],
20	  design_context: ["context"],
21	  design_route: ["route"],
22	  design_inspect: ["decide"],
23	  design_decide: ["decide"],
24	  design_sdir: ["sdir", "sdir_delta"],
25	  design_reconcile: ["reconcile"],
26	  design_prepare_implementation: ["prepare"],
27	  design_validate: ["validate"],
28	};
29	
30	export function sessionPolicy(session: DesignSession): LifecyclePolicy {
31	  return session.lifecycle_policy ?? DEFAULT_LEGACY_POLICY;
